import{_ as o,l as s,o as e,c as n,v as i,p as l,x as t,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"摆动曲线","description":"","frontmatter":{"title":"摆动曲线","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/swing-curve.md","filePath":"litho/swing-curve.md","lastUpdated":1789023840000}'),c={name:"litho/swing-curve.md"};function m(u,a,D,E,_,A){const r=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=i('<h1 id="摆动曲线" tabindex="-1">摆动曲线 <a class="header-anchor" href="#摆动曲线" aria-label="Permalink to &quot;摆动曲线&quot;">​</a></h1><div class="epigraph"><p>胶厚变四分之一光学波长，耦合进胶的能量和驻波相位一起走；CD 跟着振荡。剂量环锁不住这条横轴。</p><footer>—— Mack 对 swing curve 的讨论；薄膜周期见 Born &amp; Wolf</footer></div><p><a href="/litho/thin-film-reflectivity">上一课</a>给出了复反射 \\(r\\)。缺口是：产线看见的不是一张 \\(r\\) 表，而是 <strong>CD（或 \\(E_\\mathrm{size}\\)）随胶厚振荡</strong>——摆动曲线（swing curve）。主干驻波课已经警告过；本课把振荡的周期、振幅与剂量闭环的分工钉死。胶厚怎么选，留给[下一课](/litho/resist-thickness-selection）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>胶厚 \\(d\\) 变，两件事同时发生：进入胶的净耦合（顶面与底面多次反射的能量）变；驻波相位变，有效产酸沿 \\(z\\) 的积分变。阈值模型下，要维持同一 CD 所需剂量振荡，固定剂量下 CD 振荡。周期在胶内约为 \\(\\lambda/(2n)\\) 量级（正入射；大角度略改）。振幅由顶面反射与底面 \\(|r|\\) 共同决定。</p><p>缺口不是再推 Fresnel 矩阵，而是：摆动的横轴是厚度，纵轴是 CD / 剂量，剂量计闭环锁的是面能量，不锁 \\(d\\)。涂覆不均、台阶上的局部厚薄，走的就是这条横轴。把 CD 摆动写成「灯漂了」，会去拧剂量而留下 BARC 事故。</p><h3 id="顶与底两头" tabindex="-1">顶与底两头 <a class="header-anchor" href="#顶与底两头" aria-label="Permalink to &quot;顶与底两头&quot;">​</a></h3><p>底面 \\(|r|\\) 大 → 驻波深，摆动振幅大，BARC 主要压这一头。顶面胶–空气（或水、或 TARC）反射大 → 多次反射的能量摆动，即使底面已暗，仍可有较小的 swing。后课 TARC 管顶头，不要在本课把两头合成「一个反射率」。</p><p><span class="marginnote">浸没改顶面介质，摆动振幅和相位都会变；BARC 仍按胶下 \\(r\\) 选。换水不自动换 BARC 厚度最优解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：同一掩模、同一剂量焦点，扫胶厚，量 CD，得 swing。模拟：用上一课的栈算 \\(I(z;d)\\)，进产酸 / 阈值，切 CD\\((d)\\)。极大极小对应驻波相位与耦合的极值。减反良好时振幅压到工艺窗以内；减反失败时一个纳米级厚度误差就能把 CD 打出规格——EPE 预算里光学行必须声明是否含这条。</p><p>高 NA：不同 \\(\\theta\\) 的周期略不同，摆动被角谱糊一截，振幅可能下降，但角平均 \\(r\\) 仍可很大。不要把「高 NA 摆动自然消失」写成定理。</p>',12)),(e(),l(p,null,{default:t(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20D%5B%22%E8%83%B6%E5%8E%9A%20d%22%5D%20--%3E%20COUP%5B%22%E5%87%80%E8%80%A6%E5%90%88%E8%83%BD%E9%87%8F%22%5D%0A%20%20D%20--%3E%20PHI%5B%22%E9%A9%BB%E6%B3%A2%E7%9B%B8%E4%BD%8D%22%5D%0A%20%20R%5B%22%E5%BA%95%E9%9D%A2%20r%22%5D%20--%3E%20PHI%0A%20%20TOP%5B%22%E9%A1%B6%E9%9D%A2%E5%8F%8D%E5%B0%84%22%5D%20--%3E%20COUP%0A%20%20COUP%20--%3E%20CD%5B%22CD(d)%20%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20PHI%20--%3E%20CD%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h3 id="与-bossung-的正交" tabindex="-1">与 Bossung 的正交 <a class="header-anchor" href="#与-bossung-的正交" aria-label="Permalink to &quot;与 Bossung 的正交&quot;">​</a></h3><p>Bossung 扫的是焦点与剂量；swing 扫的是厚度。两者都改 CD，轴不同。最佳焦可以随 \\(d\\) 微移（有效光程），于是 swing 与焦窗耦合。本课先把 \\(d\\) 轴单独画清；选厚时再与焦深交。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学厚度 \\(n d\\) 每增加 \\(\\lambda/2\\)，往返相位 \\(4\\pi n d/\\lambda\\) 转 \\(2\\pi\\)，干涉条件循环一次。故 \\(\\Delta d\\sim\\lambda/(2n)\\)。振幅 \\(\\propto\\) 两列波的对比，即顶、底反射振幅之积一类因子。CAR 的酸扩散沿 \\(z\\) 糊驻波，可以减小侧壁波纹，但对 swing 的能量耦合项帮助有限——糊的是节点，不是净剂量。因此「PEB 更狠」不是 BARC 的替代。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不指定某胶的 \\(n\\) 到小数点后三位当唯一周期。溶剂残留、致密化让有效 \\(n\\) 和 \\(d\\) 在软烤后变，摆动要以烤后厚度计量。禁止编造未公开的 swing 纳米峰峰值当「典型值」。下一课才谈选在波峰还是波谷。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>摆动曲线是 CD 或 \\(E_\\mathrm{size}\\) 对胶厚的振荡，周期约 \\(\\lambda/(2n)\\)。</li><li>底面 \\(|r|\\) 与顶面反射分别贡献振幅；剂量环不锁厚度。</li><li>与 Bossung 的 \\(z\\) 轴正交，但最佳焦可随 \\(d\\) 微移。</li><li>酸扩散糊节点，不替代减反。</li><li>下一课：在曲线上选工作点。</li><li>出处：Mack；Born &amp; Wolf；Levinson。</li></ul>',8))])}const f=o(c,[["render",m]]);export{B as __pageData,f as default};
